mapper.select:
with t as ( select bsr.id , bsr.survey_id , group_concat(case when bsi.general_biz_key = 'survey_obj_code' then fill_val end) as survey_obj_code , group_concat(case when bsi.general_biz_key = 'survey_obj_name' then fill_val end) as survey_obj_name , group_concat(case when bsi.general_biz_key = 'client_name' then fill_val end) as client_name from b_survey_record bsr, json_table( json_unquote(json_extract(fill_json, '$.surveyItems')) , '$[*]' columns ( id int PATH '$.id', item_name varchar(100) PATH '$.itemName', fill_val VARCHAR(600) PATH '$.fillVal' ) ) AS tb, b_survey_item bsi where bsi.survey_id = bsr.survey_id and bsi.general_biz_key in ('survey_obj_code', 'survey_obj_name', 'client_name') and tb.id = bsi.id group by bsr.id, bsr.survey_id ) select bsr.id , bsr.survey_id , bsr.survey_name , bsr.share_url , bsr.share_expire_at , bsr.status , t.survey_obj_code , t.survey_obj_name , t.client_name , bsr.create_time , min(case when bsra.status = 2 then bsra.modify_time end) modify_time from b_survey_record bsr join t on t.id = bsr.id left join b_survey_record_answer bsra on bsra.survey_record_id = bsr.id where bsr.flag = 1 and bsr.tenant_id = #{param.tenantId}
and (bsr.create_user_id = #{param.userId} or bsra.invitee_id = #{param.userId})
and bsr.status = #{param.status}
and t.survey_obj_code like concat('%', #{param.surveyObjCode}, '%')
and t.survey_obj_name like concat('%', #{param.surveyObjName}, '%')
group by bsr.id, bsr.survey_id, bsr.survey_name, bsr.fill_json, bsr.share_url, bsr.share_expire_at, bsr.status, bsr.create_time
